CREATE OR REPLACE FUNCTION public.enl_incident_optimistic_sync_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 a jsonb := nullif(current_setting('enl.actor',true),'')::jsonb;
 r text; sid text; active_user boolean; p jsonb; v bigint;
 ignored text[] := array['corrective','workerPublic','readReceipts','updatedAt','_syncBaseVersion','_syncVersion','_syncMutationId','lastModifiedBy','lastModifiedRole','lastModifiedPosition','lastModifiedAt'];
begin
 if a is null then raise exception 'verified_session_required' using errcode='42501'; end if;
 if a->>'role' in ('worker','field') then
   select access_role,site_id,active into r,sid,active_user from public.enl_site_personnel where personnel_id::text=a->>'id' for share;
 else
   select case when role='final' then 'manager' else role end,'',active into r,sid,active_user from public.enl_hq_users where user_id=a->>'id' for share;
 end if;
 if active_user is distinct from true or r is distinct from a->>'role' then raise exception 'forbidden' using errcode='42501'; end if;
 if tg_op='DELETE' then
   if r<>'safety' then raise exception 'forbidden' using errcode='42501'; end if;
   return old;
 end if;
 if jsonb_typeof(new.payload)<>'object' or new.payload->>'id' is distinct from new.incident_id or new.payload->>'siteId' is distinct from new.site_id then raise exception 'invalid_incident'; end if;
 if tg_op='INSERT' then
   select payload into p from public.enl_incident_shared where incident_id=new.incident_id;
   if found then return new; end if; -- ON CONFLICT invokes UPDATE validation under row lock.
 else p:=old.payload;
 end if;
 if r in ('worker','field') and (sid is distinct from new.site_id or p is not null and sid is distinct from old.site_id) then raise exception 'site_forbidden' using errcode='42501'; end if;
 if p is not null and p->>'siteId' is distinct from new.site_id then raise exception 'site_change_forbidden' using errcode='42501'; end if;
 if r='worker' and p is not null and p->>'reporterId' is distinct from a->>'id' then raise exception 'owner_forbidden' using errcode='42501'; end if;
 if r in ('manager','executive') then
   if p is null or p->>'status' not in ('approved','closed') or (p-ignored || jsonb_build_object('corrective',p->'corrective')) is distinct from (new.payload-ignored || jsonb_build_object('corrective',new.payload->'corrective')) then raise exception 'reader_write_forbidden' using errcode='42501'; end if;
 elsif r<>'safety' and p->>'status' in ('approved','closed') and p-ignored is distinct from new.payload-ignored then
   raise exception 'approved_report_read_only' using errcode='42501';
 end if;
 if r<>'safety' and p is null and (new.payload->>'status'<>'reported' or new.payload->>'approvedAt' is not null or new.payload->'importHistory' is not null) then raise exception 'approval_forbidden' using errcode='42501'; end if;
 if r in ('worker','field') and p is not null then
   if (new.payload->>'status' is distinct from p->>'status' and not(p->>'status'='rejected' and new.payload->>'status'='reported')) or (new.payload->>'approvedAt' is distinct from p->>'approvedAt') or (new.payload->>'approvedBy' is distinct from p->>'approvedBy') or (new.payload->'readReceipts' is distinct from p->'readReceipts') then raise exception 'approval_forbidden' using errcode='42501'; end if;
   if new.payload->'corrective'->>'status' in ('approved','rejected') and new.payload->'corrective'->>'status' is distinct from p->'corrective'->>'status' then raise exception 'action_approval_forbidden' using errcode='42501'; end if;
   if p->'corrective'->>'status'='approved' and p->'corrective' is distinct from new.payload->'corrective' then raise exception 'approved_action_read_only' using errcode='42501'; end if;
 end if;
 if not(new.payload ? '_syncBaseVersion') or jsonb_typeof(new.payload->'_syncBaseVersion')<>'number' or coalesce(new.payload->>'_syncBaseVersion','') !~ '^[0-9]+$' or coalesce(new.payload->>'_syncMutationId','')='' then raise exception 'enl_sync_conflict_missing_version' using errcode='40001'; end if;
 v:=coalesce((p->>'_syncVersion')::bigint,0);
 if (new.payload->>'_syncBaseVersion')::bigint<>v then raise exception 'enl_sync_conflict_version' using errcode='40001'; end if;
 new.payload:=jsonb_set(new.payload,'{_syncVersion}',to_jsonb(v+1));
 return new;
end $function$

